import json
d=json.load(open('splitviews.json'))
def walk(n,out):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        elif t=='reference': out.append('['+str(n.get('identifier','')).split('/')[-1]+']')
        for k,v in n.items():
            if k in ('text','code','identifier'): continue
            walk(v,out)
        if t in ('paragraph','heading','listItem','aside'): out.append('\n')
    elif isinstance(n,list):
        for i in n: walk(i,out)
o=[]
walk(d.get('primaryContentSections',d),o)
